func (this *Test_org_eclipse_swt_graphics_GC) Test_getFontMetrics_notAffectedByTransform() {
	var font *swt.Font = swt.NewFontDeviceNameHeightStyle(upcastswtDisplayToswtDevice(this.display), "NonExistentSWTTestFont", 24, swt.NORMAL)
	var scaleTransform *swt.Transform = swt.NewTransformDeviceM11M12M21M22DxDy(upcastswtDisplayToswtDevice(this.display), 3.0, 0.0, 0.0, 3.0, 0.0, 0.0)
	{
		defer func() {
			scaleTransform.Dispose()
			font.Dispose()
		}()
		this.gc.SetFont(font)
		this.gc.SetTransform(scaleTransform)
		var metricsWithTransform float64 = this.gc.GetFontMetrics().GetAverageCharacterWidth()
		this.gc.SetTransform(nil)
		var metricsAfterClearingTransform float64 = this.gc.GetFontMetrics().GetAverageCharacterWidth()
		this.gc.SetFont(font)
		var metricsAfterReSettingFont float64 = this.gc.GetFontMetrics().GetAverageCharacterWidth()
		this.gc.SetTransform(scaleTransform)
		var metricsWithTransformAgain float64 = this.gc.GetFontMetrics().GetAverageCharacterWidth()
		junit.AssertAll(func() {
			junit.AssertEqualsDelta(float64(metricsWithTransform), float64(metricsAfterClearingTransform), float64(float64(0)), "Font metrics must not change after clearing the transform")
		}, func() {
			junit.AssertEqualsDelta(float64(metricsAfterClearingTransform), float64(metricsAfterReSettingFont), float64(float64(0)), "Font metrics must not change when re-setting the font without transform")
		}, func() {
			junit.AssertEqualsDelta(float64(metricsAfterReSettingFont), float64(metricsWithTransformAgain), float64(float64(0)), "Font metrics must not be scaled when the transform is re-applied")
		})
	}
}

