func (this *Test_org_eclipse_swt_graphics_GC) Test_setLineAttributes_I() {
	var width int32 = 1
	var cap int32 = 3
	var join int32 = 2
	var style int32 = 6
	var dashes []float32 = []float32{1.2, 3.3}
	var dashOffset float32 = 3.3
	var miterLimit float32 = 2.6
	var passedLineAttributes *swt.LineAttributes = swt.NewLineAttributesWidthCapJoinStyleDashDashOffsetMiterLimit(float32(width), cap, join, style, dashes, dashOffset, miterLimit)
	this.gc.SetLineAttributes(passedLineAttributes)
	junit.AssertEquals(int32(width), int32(this.gc.GetLineWidth()), "unexpected line width")
	junit.AssertEquals(int32(cap), int32(this.gc.GetLineCap()), "unexpected line cap")
	junit.AssertEquals(int32(join), int32(this.gc.GetLineJoin()), "unexpected line join")
	junit.AssertEquals(int32(style), int32(this.gc.GetLineStyle()), "unexpected line style")
	junit.AssertEquals(swt.NewLineAttributesWidthCapJoinStyleDashDashOffsetMiterLimit(float32(width), cap, join, style, dashes, dashOffset, miterLimit), this.gc.GetLineAttributes(), "actual line attributes differ from the ones that have been set")
	junit.AssertEqualsDelta(float32(float32(width)), float32(passedLineAttributes.Width), float32(0.0), "setter call changed line width")
	var currentZoom int32 = swt.DPIUtilGetDeviceZoom()
	var alternateZoom int32
	if currentZoom == 100 {
		alternateZoom = 200
	} else {
		alternateZoom = 100
	}
	this.image.GetImageDataZoom(alternateZoom)
	junit.AssertEquals(int32(width), int32(this.gc.GetLineWidth()), "unexpected line width")
	junit.AssertEquals(int32(cap), int32(this.gc.GetLineCap()), "unexpected line cap")
	junit.AssertEquals(int32(join), int32(this.gc.GetLineJoin()), "unexpected line join")
	junit.AssertEquals(int32(style), int32(this.gc.GetLineStyle()), "unexpected line style")
	junit.AssertEquals(swt.NewLineAttributesWidthCapJoinStyleDashDashOffsetMiterLimit(float32(width), cap, join, style, dashes, dashOffset, miterLimit), this.gc.GetLineAttributes(), "actual line attributes differ from the ones that have been set")
	junit.AssertEqualsDelta(float32(float32(width)), float32(passedLineAttributes.Width), float32(0.0), "setter call changed line width")
	this.gc.SetLineAttributes(swt.NewLineAttributes(float32(1)))
	junit.AssertEquals(swt.NewLineAttributes(float32(1)), this.gc.GetLineAttributes())
}

