func (this *Test_org_eclipse_swt_graphics_GC) Test_bug493455_drawImageAlpha_srcPos() {
	junit.AssumeFalse(SwtTestUtilIsCocoa, "https://github.com/eclipse-platform/eclipse.platform.swt/issues/40 causes test to fail on Mac")
	var red *swt.RGB = swt.NewRGB(255, 0, 0)
	var green *swt.RGB = swt.NewRGB(0, 255, 0)
	var initImageData *swt.ImageData = swt.NewImageData(200, 200, 32, swt.NewPaletteDataRedMaskGreenMaskBlueMask(0xff, 0xff00, 0xff0000))
	initImageData.AlphaData = make([]int8, 200*200)
	var srcImage *swt.Image = swt.NewImageDeviceData(upcastswtDisplayToswtDevice(this.display), initImageData)
	var srcImageGc *swt.GC = swt.NewGCDrawable(srcImage)
	srcImageGc.SetAdvanced(true)
	srcImageGc.SetBackground(swt.NewColorRgb(red))
	srcImageGc.FillRectangle(0, 0, 200, 200)
	srcImageGc.SetBackground(swt.NewColorRgb(green))
	srcImageGc.FillRectangle(100, 50, 100, 150)
	srcImageGc.Dispose()
	this.gc.DrawImageImageSrcXSrcYSrcWidthSrcHeightDestXDestYDestWidthDestHeight(srcImage, 100, 50, 100, 150, 0, 0, 100, 150)
	var srcImageData *swt.ImageData = srcImage.GetImageData()
	srcImage.Dispose()
	var testImageData *swt.ImageData = this.image.GetImageData()
	junit.AssertNotNull(srcImageData.AlphaData)
	for i := int32(0); i < 200; i++ {
		for j := int32(0); j < 200; j++ {
			var expected *swt.RGB
			if i < 100 || j < 50 {
				expected = red
			} else {
				expected = green
			}
			var actual *swt.RGB = srcImageData.Palette.GetRGB(srcImageData.GetPixel(i, j))
			junit.AssertEquals(expected, actual)
		}
	}
	for i := int32(0); i < 100; i++ {
		for j := int32(0); j < 150; j++ {
			var rgb *swt.RGB = testImageData.Palette.GetRGB(testImageData.GetPixel(i, j))
			junit.AssertEquals(green, rgb)
		}
	}
}

func (this *Test_org_eclipse_swt_graphics_GC) Test_drawLine_noSingularitiesIn45DregreeRotation() {
	var imageSize int32 = 3
	var centerPixel int32 = imageSize / 2
	var image *swt.Image = swt.NewImageDeviceWidthHeight(upcastswtDisplayToswtDevice(swt.DisplayGetDefault()), imageSize, imageSize)
	var gc *swt.GC = swt.NewGCDrawable(image)
	var rotation *swt.Transform = swt.NewTransform(gc.GetDevice())
	gc.GetTransform(rotation)
	{
		defer func() {
			rotation.Dispose()
			gc.Dispose()
			image.Dispose()
		}()
		rotation.Translate(float32(centerPixel), float32(centerPixel))
		rotation.Rotate(float32(45))
		rotation.Translate(float32(-centerPixel), float32(-centerPixel))
		gc.SetTransform(rotation)
		gc.DrawLine(centerPixel, centerPixel, centerPixel+1, centerPixel)
		junit.AssertNotEquals(int32(-1), int32(image.GetImageData().GetPixel(centerPixel, centerPixel)), "line is not drawn with 45 degree rotation")
	}
}

func (this *Test_org_eclipse_swt_graphics_GC) Test_bug1288_createGCFromImageFromNonDisplayThread() {
	var exceptionReference any = func() any { panic("j2go: unresolved new AtomicReference<Exception>") }()
	var thread any = func() any {
		_ = []any{jrt.NewRunnable(func() {
			func() {
				defer func() {
					r := recover()
					if r == nil {
						return
					}
					if e, ok := r.(error); ok {
						_ = e
						func() any { _ = []any{exceptionReference, e}; panic("j2go: unresolved call set") }()
					} else {
						panic(r)
					}
				}()
				var image *swt.Image = swt.NewImageDeviceWidthHeight(nil, 100, 100)
				var gc *swt.GC = swt.NewGCDrawable(image)
				gc.Dispose()
				image.Dispose()
			}()
		})}
		return nil
	}()
	func() any { _ = []any{thread}; panic("j2go: unresolved call start") }()
	func() any { _ = []any{thread}; panic("j2go: unresolved call join") }()
	junit.AssertNull(func() error { _ = []any{exceptionReference}; panic("j2go: unresolved call get") }(), "Creating a GC from an Image without a device threw an exception")
}

func (this *Test_org_eclipse_swt_graphics_GC) Test_noMemoryLeakAfterDispose() {
	var testGC *swt.GC = swt.NewGCDrawable(this.display)
	var image *swt.Image = swt.NewImageDeviceWidthHeight(upcastswtDisplayToswtDevice(this.display), 1, 1)
	{
		defer func() {
			image.Dispose()
		}()
		testGC.SetFont(this.display.GetSystemFont())
		testGC.SetClippingOverload2(swt.NewRectangle(0, 0, 2, 2))
		testGC.DrawImage(image, 0, 0)
		testGC.DrawText("Test", 0, 0)
		testGC.DrawLine(0, 0, 5, 5)
		var testGCReference any = func() any { _ = []any{testGC}; panic("j2go: unresolved new WeakReference<GC>") }()
		testGC.Dispose()
		testGC = nil
		func() any { panic("j2go: unresolved call gc") }()
		junit.AssertNull(func() *swt.GC { _ = []any{testGCReference}; panic("j2go: unresolved call get") }())
	}
}

func (this *Test_org_eclipse_swt_graphics_GC) GetRealRGB(colorLike swt.ColorLike) *swt.RGB {
	var color *swt.Color
	if colorLike != nil {
		color = colorLike.AsColor()
	}
	_ = color
	var gcDrawer swt.ImageGcDrawer = &ImageGcDrawerFunc{fn: func(imageGc *swt.GC, width int32, height int32) {
		imageGc.SetBackground(color)
		imageGc.SetForeground(color)
		imageGc.FillRectangle(0, 0, width, height)
	}}
	var colorImage *swt.Image = swt.NewImageDeviceImageGcDrawerWidthHeight(upcastswtDisplayToswtDevice(this.display), gcDrawer, 10, 10)
	var imageData *swt.ImageData = colorImage.GetImageData()
	var palette *swt.PaletteData = imageData.Palette
	colorImage.Dispose()
	var pixel int32 = imageData.GetPixel(0, 0)
	return palette.GetRGB(pixel)
}

func (this *Test_org_eclipse_swt_graphics_GC) ExecuteWithNonDefaultDeviceZoom(executable jrt.Runnable) {
	var previousDeviceZoom int32 = swt.DPIUtilGetDeviceZoom()
	swt.DPIUtilSetDeviceZoom(200)
	this.gc.Dispose()
	this.gc = swt.NewGCDrawable(this.image)
	{
		defer func() {
			swt.DPIUtilSetDeviceZoom(previousDeviceZoom)
		}()
		executable.Run()
	}
}

